username_backfill.query:
with normalized as (
 select p.id, lower(regexp_replace(coalesce(nullif(split_part(u.email,'@',1),''),'member'),'[^a-z0-9_-]','_','g')) as raw_base
 from public.profiles p left join auth.users u on u.id=p.id
), candidates as (
 select id, case when length(trim(both '_' from raw_base))<3 then 'member' else left(trim(both '_' from raw_base),20) end as base
 from normalized
), numbered as (
 select id,base,row_number() over(partition by base order by id) as duplicate_index from candidates
), proposed as (
 select case when duplicate_index=1 then base else left(base,20)||'_'||duplicate_index::text end as username from numbered
)
select (select count(*) from proposed) as evaluated_profiles,
 (select count(*) from proposed where username !~ '^[a-z0-9][a-z0-9_-]{2,23}$') as invalid_usernames,
 (select count(*) from (select username from proposed group by username having count(*)>1) d) as username_collision_groups,
 (select count(*) from public.profiles where membership_status='active') as active_profiles_to_number;

auth_alias.query:
with normalized as (
 select p.id, lower(regexp_replace(coalesce(nullif(split_part(u.email,'@',1),''),'member'),'[^a-z0-9_-]','_','g')) as raw_base
 from public.profiles p left join auth.users u on u.id=p.id
), candidates as (
 select id, case when length(trim(both '_' from raw_base))<3 then 'member' else left(trim(both '_' from raw_base),20) end as base
 from normalized
), numbered as (
 select id,base,row_number() over(partition by base order by id) as duplicate_index from candidates
), proposed as (
 select id, case when duplicate_index=1 then base else left(base,20)||'_'||duplicate_index::text end as username from numbered
)
select count(*) as evaluated_accounts, count(*) filter(where u.email = proposed.username || '@soulbound.internal') as matching_username_auth_alias, count(*) filter(where u.email is distinct from proposed.username || '@soulbound.internal') as legacy_auth_alias_mismatch from proposed join auth.users u on u.id=proposed.id;
